/**
 * Social card. An inline SVG keeps the card in the same design language as the
 * site with no build step and no binary in the repo — see docs/PUBLIC_SITE.md
 * for the PNG follow-up some social networks need.
 *
 * The lockup here is the *same* mark the favicon, the sign-in page and the
 * dashboard header draw (issue #35): `MARK_PATH` and `MARK_BLUE` come straight
 * from `src/pages.ts`, so the thing somebody sees in a Slack unfurl and the
 * thing they see when they click through cannot drift apart. Nested `<svg>`
 * rather than a copied path, so the mark keeps its own 32×32 coordinate space.
 */
export function ogImageSvg(): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630" role="img" aria-label="${SITE.name} — ${SITE.tagline}">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="#06070a"/><stop offset="100%" stop-color="#111827"/>
    </linearGradient>
  </defs>
  <rect width="1200" height="630" fill="url(#bg)"/>
  <circle cx="1050" cy="90" r="260" fill="#0a84ff" opacity="0.16"/>
  <circle cx="150" cy="600" r="220" fill="#64d2ff" opacity="0.12"/>
  <svg x="96" y="88" width="72" height="72" viewBox="0 0 32 32">
    <rect width="32" height="32" rx="8" fill="${MARK_BLUE}"/>
    <path d="${MARK_PATH}" fill="white"/>
  </svg>
  <g font-family="-apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Segoe UI', Helvetica, Arial, sans-serif">
    <text x="184" y="136" fill="#f5f7fb" font-size="40" font-weight="700" letter-spacing="-1">${SITE.name}</text>
    <text x="96" y="260" fill="#f5f7fb" font-size="86" font-weight="700" letter-spacing="-3">Claude creates.</text>
    <text x="96" y="356" fill="#f5f7fb" font-size="86" font-weight="700" letter-spacing="-3">We share.</text>
    <text x="96" y="434" fill="#a6adbb" font-size="34">Access-protected hosting for what Claude builds.</text>
    <text x="96" y="480" fill="#a6adbb" font-size="34">Agent-native publishing. Versioned. Audited.</text>
  </g>
</svg>
`;
}

/** Edge length of the square logo raster served at `/logo.png`. */
export const LOGO_PNG_SIZE = 512;

/**
 * Square logo — the rtfx mark on its own, nothing else in the frame.
 *
 * Deliberately *not* the social card. `Organization.logo` in JSON-LD is consumed
 * as a logo: a knowledge panel crops it towards square and Google's own guidance
 * is that it be the mark rather than a banner. Pointing it at the 1200×630
 * `/og.png` — which is nine parts headline copy to one part mark — handed every
 * consumer of the graph a wordy landscape image where a logo was promised.
 *
 * Same `MARK_PATH` and `MARK_BLUE` as the favicon, the sign-in page, the
 * dashboard header and the social card, on the mark's own 32×32 grid, so there
 * is still exactly one mark in the product (issue #35). Transparent outside the
 * rounded tile, so it sits on a light or a dark panel equally well.
 */
export function logoSvg(size: number = LOGO_PNG_SIZE): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 32 32" role="img" aria-label="${SITE.name}">
  <rect width="32" height="32" rx="8" fill="${MARK_BLUE}"/>
  <path d="${MARK_PATH}" fill="white"/>
</svg>
`;
}

/**
 * The rasters, and the fingerprint of what they were rendered from. All four
 * constants below are written by `node scripts/generate-brand-rasters.mjs` —
 * never hand-edit them.
 *
 * The images are checked in as base64 rather than built at deploy time because a
 * Worker has no image encoder, and a binary asset pipeline is more machinery
 * than two static pictures are worth. What that costs is drift, and it has
 * already been paid once: `ogImageSvg()` was redesigned — new mark treatment,
 * new lockup position, new copy — while `OG_IMAGE_PNG_BASE64` went on serving
 * the previous design to every unfurl, `og:image` and `twitter:image` on the
 * site. Nothing failed, because nothing was checking.
 *
 * Two things check now, and they fail for different reasons (see
 * `test/brand-raster.test.ts`):
 *
 *  - **The source digests.** SHA-256 of the exact SVG string each PNG was
 *    rendered from. Any edit to the artwork or the copy inside it — down to a
 *    space — changes the digest and fails the suite until the rasters are
 *    regenerated. This is the check that would have caught the redesign.
 *  - **The pixels.** The test decodes both PNGs and reads the mark's tile at the
 *    coordinates the *current* SVG puts it at. A digest can be updated without
 *    re-rendering; a pixel cannot.
 */
/** SHA-256 (hex) of the `ogImageSvg()` string `OG_IMAGE_PNG_BASE64` was rendered from. */
export const OG_IMAGE_SVG_SHA256 = "c0e65460abbb1e179b1290eedff38a02dae1bb393e76cc49d0599a9e7d3ee627";

/** SHA-256 (hex) of the `logoSvg()` string `LOGO_PNG_BASE64` was rendered from. */
export const LOGO_SVG_SHA256 = "927c0ee79521f976714c9b745cea3065899a62eb204d74e7bf35989db369f447";

/** PNG social card for OpenGraph/Twitter previews. Generated from the same rtfx mark/copy as ogImageSvg. */
export const OG_IMAGE_PNG_BASE64 = "";

/** Square PNG logo for `Organization.logo` in JSON-LD and any consumer wanting a mark, not a card. Generated from logoSvg. */
export const LOGO_PNG_BASE64 = "";
